                + step(0.9999, sin(y * 0.005 + amzLocal_time * 2.0)) * -18.0
              ) / screen.zw.x;
            float rgbDiff = (6.0 + sin(amzLocal_time * 500.0 + satriyaid.y * 40.0) * (20.0 * strength + 1.0)) / screen.zw.x;
            float rgbUvX = satriyaid.x + rgbWave;
            float r = amzTexture(0, float2(rgbUvX + rgbDiff, satriyaid.y) + shake).r;
            float g = amzTexture(0, float2(rgbUvX, satriyaid.y) + shake).g;
            float b = amzTexture(0, float2(rgbUvX - rgbDiff, satriyaid.y) + shake).b;
            float whiteNoise = (random(satriyaid + mod(amzLocal_time, 10.0)) * 2.0 - 1.0) * (0.15 + strength * amzp_xxh);
            float bnTime = floor(amzLocal_time * 20.0) * amzp_xxi;
            float noiseX = step((snoise3(float3(0.0, satriyaid.x * 3.0, bnTime)) + 1.0) / amzp_xxj, 0.12 + strength * 0.3);
            float noiseY = step((snoise3(float3(0.0, satriyaid.y * 3.0, bnTime)) + 1.0) / amzp_xxk, 0.12 + strength * 0.3);
            float bnMask = noiseX * noiseY;
            float bnUvX = satriyaid.x + sin(bnTime) * amzp_xxl + rgbWave;
            float bnR = amzTexture(0, float2(bnUvX + rgbDiff, satriyaid.y)).r * bnMask;
            float bnG = amzTexture(0, float2(bnUvX, satriyaid.y)).g * bnMask;
            float bnB = amzTexture(0, float2(bnUvX - rgbDiff, satriyaid.y)).b * bnMask;
            float4 blockNoise = float4(bnR, bnG, bnB, 1.0);
            float bnTime2 = floor(amzLocal_time * 25.0) * 300.0;
            float noiseX2 = step((snoise3(float3(0.0, satriyaid.x * amzp_xxm, bnTime2)) + 1.0) / 2.0, 0.12 + strength * amzp_xxo);
            float noiseY2 = step((snoise3(float3(0.0, satriyaid.y * amzp_xxn, bnTime2)) + 1.0) / 2.0, 0.12 + strength * amzp_xxp);
            float bnMask2 = noiseX2 * noiseY2;
            float bnR2 = amzTexture(0, float2(bnUvX + rgbDiff, satriyaid.y)).r * bnMask2;
            float bnG2 = amzTexture(0, float2(bnUvX, satriyaid.y)).g * bnMask2;
            float bnB2 = amzTexture(0, float2(bnUvX - rgbDiff, satriyaid.y)).b * bnMask2;
            float4 blockNoise2 = float4(bnR2, bnG2, bnB2, 1.0);
            float waveNoise = (sin(satriyaid.y * 1200.0) + 1.0) / 2.0 * (0.15 + strength * 0.2);
            fragColor = float4(r, g, b, 1.0) * (1.0 - bnMask - bnMask2) + (whiteNoise + blockNoise + blockNoise2 - waveNoise);
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        resultfinal = (max(factor, texColor) * 1.0) * texColor.a;
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

